1	/**
2	 * Same-session goal-round driver over public agent, session, and goal services.
3	 * @module @deepseek-ai/dsh-goal-round-driver
4	 */
5	
6	import { isDeepStrictEqual } from 'node:util'
7	import { FiberState } from '@deepseek-ai/cordis'
8	import type { Context } from '@deepseek-ai/cordis'
9	import type { Agent, PreStepDecision } from '@deepseek-ai/dsh-agent'
10	import type { GoalMessageSource, GoalRef, GoalView } from '@deepseek-ai/dsh-goal'
11	import { createUserMessage } from '@deepseek-ai/dsh-llm'
12	import type { ContentBlock, MessageId, MessageSource } from '@deepseek-ai/dsh-llm'
13	import type { Session, SessionEvent, UserMessage } from '@deepseek-ai/dsh-session'
14	import { renderGoalRoundPrompt } from './prompt.ts'
15	
16	export { renderGoalRoundPrompt } from './prompt.ts'
17	
18	export const name = 'goal-round-driver'
19	export const inject = ['agents', 'goals', 'sessions']
20	
21	/** Identity reserved before a goal continuation enters the agent inbox. */
22	interface RoundIdentity {
23	  readonly goalId: GoalRef['id']
24	  readonly revision: number
25	  readonly round: number
26	}
27	
28	/** One queued, claimed, or admitted goal message retained until whole-agent quiescence. */
29	interface RoundAttempt extends RoundIdentity {
30	  readonly messageId: MessageId
31	  readonly content: ContentBlock[]
32	  phase: 'queued' | 'claimed' | 'admitted'
33	  cancelled: boolean
34	  stale: boolean
35	}
36	
37	/** Serialized process-local scheduling state for one exact Agent lifecycle. */
38	interface DriverState {
39	  readonly agent: Agent
40	  attempt: RoundAttempt | undefined
41	  competingQueued: boolean
42	  needsCheckpoint: boolean
43	  requested: boolean
44	  run: Promise<void> | undefined
45	  stopping: boolean
46	}
47	
48	/** Whether a source identifies an automatic, positive-numbered goal round. */
49	function isGoalRoundSource(source: MessageSource): source is GoalMessageSource {
50	  return source.kind === 'goal' && source.round > 0
51	}
52	
53	/** Compare a source to one reserved identity. */
54	function sameRound(source: GoalMessageSource, round: RoundIdentity): boolean {
55	  return source.goalId === round.goalId
56	    && source.revision === round.revision
57	    && source.round === round.round
58	}
59	
60	/** Compare the complete queued record to the driver's reservation. */
61	function sameQueued(content: ContentBlock[], source: MessageSource, attempt: RoundAttempt): boolean {
62	  return isGoalRoundSource(source) && sameRound(source, attempt) && isDeepStrictEqual(content, attempt.content)
63	}
64	
65	/** Exact current ref for a view. */
66	function goalRef(goal: GoalView): GoalRef {
67	  return { id: goal.id, revision: goal.revision }
68	}
69	
70	/** Human-readable unexpected values for logs. */
71	function renderThrown(value: unknown): string {
72	  return value instanceof Error ? value.message : String(value)
73	}
74	
75	/** Install automatic same-session continuation and its race fences. */
76	export function apply(ctx: Context): void {
77	  const states = new Map<Agent, DriverState>()
78	
79	  /** Create state for an exact currently live agent. */
80	  function stateFor(agent: Agent): DriverState {
81	    const existing = states.get(agent)
82	    if (existing !== undefined) return existing
83	    const state: DriverState = {
84	      agent,
85	      attempt: undefined,
86	      competingQueued: false,
87	      needsCheckpoint: false,
88	      requested: false,
89	      run: undefined,
90	      stopping: false,
91	    }
92	    states.set(agent, state)
93	    return state
94	  }
95	
96	  /** Read only when the exact Agent remains live. */
97	  function currentGoal(state: DriverState): GoalView | undefined {
98	    if (ctx.agents.get(state.agent.id) !== state.agent) return undefined
99	    return ctx.goals.get(state.agent)
100	  }
101	
102	  /** Whether this exact lifecycle is quiescent with no competing prompt. */
103	  function readyToDrive(state: DriverState): boolean {
104	    return ctx.fiber.state === FiberState.ACTIVE
105	      && !state.stopping
106	      && ctx.agents.get(state.agent.id) === state.agent
107	      && state.agent.status === 'idle'
108	      && !state.competingQueued
109	  }
110	
111	  /** Recheck every condition that an awaited checkpoint may have changed. */
112	  function readyAfterCheckpoint(state: DriverState): boolean {
113	    return readyToDrive(state) && !state.needsCheckpoint
114	  }
115	
116	  /** Remove automatic authority while preserving the durable phase. */
117	  function disarm(state: DriverState): void {
118	    try {
119	      const goal = currentGoal(state)
120	      if (goal?.activation === 'armed') ctx.goals.disarm(state.agent)
121	    } catch (error: unknown) {
122	      ctx.logger.warn(`goal-round-driver: could not disarm agent "${state.agent.id}": ${renderThrown(error)}`)
123	    }
124	  }
125	
126	  /** Preserve claimed step context when this driver drops only its own round. */
127	  function restoreOtherClaimed(agent: Agent, messages: UserMessage[], messageId: MessageId): void {
128	    const retained = messages.filter(message => message.id !== messageId
129	      && !(message.source.kind === 'goal' && message.source.round === 0))
130	    for (const message of retained.toReversed()) {
131	      if (agent.inbox.nextStep.some(candidate => candidate.id === message.id)
132	        || agent.inbox.nextTurn.some(candidate => candidate.id === message.id)) continue
133	      agent.inbox.prepend('next-step', message)
134	    }
135	  }
136	
137	  /** Process admitted work at quiescence, then reserve at most one next round. */
138	  async function drive(state: DriverState): Promise<void> {
139	    const { agent } = state
140	    if (!readyToDrive(state)) return
141	
142	    if (state.needsCheckpoint) {
143	      state.needsCheckpoint = false
144	      try {
145	        await ctx.sessions.flush(agent.session)
146	      } catch (error: unknown) {
147	        ctx.logger.warn(`goal-round-driver: durability checkpoint failed for agent "${agent.id}": ${renderThrown(error)}`)
148	        disarm(state)
149	        return
150	      }
151	      // A mutation or ordinary prompt may have arrived while the checkpoint
152	      // was settling. Give it its own checkpoint / turn before reserving.
153	      if (!readyAfterCheckpoint(state)) return
154	    }
155	
156	    const attempt = state.attempt
157	    if (attempt !== undefined) {
158	      state.attempt = undefined
159	      state.needsCheckpoint = true
160	      state.requested = true
161	      return
162	    }
163	
164	    const goal = currentGoal(state)
165	    if (goal === undefined || goal.phase !== 'active' || goal.activation !== 'armed') return
166	    if (goal.roundsStarted >= goal.maxGoalRounds) {
167	      ctx.goals.block(agent, goalRef(goal), {
168	        code: 'round-limit',
169	        message: `Goal reached its configured limit of ${goal.maxGoalRounds} rounds.`,
170	      })
171	      return
172	    }
173	
174	    const round = goal.roundsStarted + 1
175	    const content = renderGoalRoundPrompt(goal, round)
176	    const message = createUserMessage({
177	      content,
178	      source: { kind: 'goal', goalId: goal.id, revision: goal.revision, round },
179	    })
180	    const reservation: RoundAttempt = {
181	      goalId: goal.id,
182	      revision: goal.revision,
183	      round,
184	      messageId: message.id,
185	      content,
186	      phase: 'queued',
187	      cancelled: false,
188	      stale: false,
189	    }
190	    state.attempt = reservation
191	    try {
192	      agent.followup(message)
193	    } catch (error: unknown) {
194	      state.attempt = undefined
195	      ctx.logger.warn(`goal-round-driver: could not queue round ${round} for agent "${agent.id}": ${renderThrown(error)}`)
196	      const latest = currentGoal(state)
197	      if (latest !== undefined && latest.id === goal.id && latest.revision === goal.revision
198	        && latest.phase === 'active' && latest.activation === 'armed') {
199	        ctx.goals.block(agent, goalRef(latest), {
200	          code: 'queue-failed',
201	          message: `Could not queue goal round ${round}: ${renderThrown(error)}`,
202	        })
203	      }
204	    }
205	  }
206	
207	  /** Coalesce triggers onto one agent-local serialized driver. */
208	  function requestDrive(state: DriverState): void {
209	    /* v8 ignore next -- teardown may race a final trigger after synchronously closing the step fence */
210	    if (state.stopping) return
211	    state.requested = true
212	    if (state.run !== undefined) return
213	    let run: Promise<void>
214	    try {
215	      run = ctx.agents.withoutInitiator(async () => {
216	        while (state.requested && !state.stopping) {
217	          state.requested = false
218	          try {
219	            await drive(state)
220	          } catch (error: unknown) {
221	            ctx.logger.warn(`goal-round-driver: driver failed for agent "${state.agent.id}": ${renderThrown(error)}`)
222	            disarm(state)
223	          }
224	        }
225	      })
226	    } catch (error: unknown) {
227	      ctx.logger.warn(`goal-round-driver: could not start driver for agent "${state.agent.id}": ${renderThrown(error)}`)
228	      disarm(state)
229	      return
230	    }
231	    state.run = run
232	    const retire = (): void => {
233	      state.run = undefined
234	      if (state.requested && !state.stopping) requestDrive(state)
235	    }
236	    void run.then(retire, (error: unknown) => {
237	      ctx.logger.warn(`goal-round-driver: driver task rejected for agent "${state.agent.id}": ${renderThrown(error)}`)
238	      disarm(state)
239	      retire()
240	    })
241	  }
242	
243	  // One composite effect keeps the step fence installed until this
244	  // plugin's own scheduling tasks settle.
245	  ctx.effect(function* () {
246	    ctx.on('agent/error', ({ agent }) => {
247	      const state = stateFor(agent)
248	      disarm(state)
249	    })
250	
251	    ctx.on('agent/created', ({ agent }) => { stateFor(agent) })
252	    ctx.on('agent/disposed', ({ agent }) => { states.delete(agent) })
253	    ctx.on('agent/session-start', ({ agent }) => {
254	      const state = stateFor(agent)
255	      state.attempt = undefined
256	      state.competingQueued = false
257	      state.needsCheckpoint = false
258	    })
259	    ctx.on('agent/status', ({ agent, status }) => {
260	      const state = stateFor(agent)
261	      if (status === 'idle') {
262	        state.competingQueued = false
263	        const attempt = state.attempt
264	        const goal = currentGoal(state)
265	        if ((attempt?.phase === 'queued' || attempt?.phase === 'claimed' || attempt?.cancelled)
266	          && goal?.phase === 'active' && goal.activation === 'armed') {
267	          state.attempt = undefined
268	          try {
269	            ctx.goals.pause(agent, goalRef(goal))
270	          } catch (error: unknown) {
271	            ctx.logger.warn(`goal-round-driver: could not pause cancelled goal for agent "${agent.id}": ${renderThrown(error)}`)
272	            disarm(state)
273	          }
274	        }
275	        requestDrive(state)
276	      }
277	    })
278	    ctx.on('goal/changed', ({ agent }) => {
279	      const state = stateFor(agent)
280	      state.needsCheckpoint = true
281	      requestDrive(state)
282	    })
283	
284	    ctx.on('agent/inbox/inserted', ({ agent, message }) => {
285	      if (!agent.inbox.nextTurn.some(candidate => candidate.id === message.id)) return
286	      const state = stateFor(agent)
287	      const attempt = state.attempt
288	      if (attempt !== undefined && sameQueued(message.content, message.source, attempt)) return
289	      state.competingQueued = true
290	      if (attempt?.phase === 'queued') attempt.stale = true
291	    })
292	    ctx.on('agent/inbox/claimed', ({ agent, message }) => {
293	      const state = stateFor(agent)
294	      const attempt = state.attempt
295	      if (attempt !== undefined && sameQueued(message.content, message.source, attempt)) {
296	        attempt.phase = 'claimed'
297	      }
298	    })
299	    ctx.on('agent/inbox/discarded', ({ agent, message }) => {
300	      const state = stateFor(agent)
301	      const attempt = state.attempt
302	      if (attempt !== undefined && sameQueued(message.content, message.source, attempt)) {
303	        attempt.cancelled = true
304	      }
305	    })
306	
307	    ctx.on('session/event', (session: Session, event: SessionEvent) => {
308	      const agent = ctx.agents.get(session.id)
309	      if (agent === undefined || agent.session !== session) return
310	      const state = stateFor(agent)
311	      switch (event.type) {
312	        case 'user/message':
313	          if (state.attempt !== undefined && event.data.id === state.attempt.messageId) {
314	            state.attempt.phase = 'admitted'
315	          }
316	          return
317	        case 'turn/end':
318	          if (event.data.reason.kind === 'max-tokens') {
319	            disarm(state)
320	            return
321	          }
322	          if (event.data.reason.kind !== 'aborted') return
323	          if (state.attempt?.phase === 'claimed' || state.attempt?.phase === 'admitted') {
324	            state.attempt.cancelled = true
325	          }
326	          else disarm(state)
327	          return
328	        default:
329	          return
330	      }
331	    })
332	
333	    /** Fail closed unless the queued prompt still owns the exact live revision. */
334	    function validReservation(
335	      state: DriverState,
336	      content: ContentBlock[],
337	      source: GoalMessageSource,
338	    ): boolean {
339	      const attempt = state.attempt
340	      const goal = currentGoal(state)
341	      return ctx.fiber.state === FiberState.ACTIVE
342	        && !state.stopping && attempt !== undefined && attempt.phase === 'claimed'
343	      && !attempt.stale && sameQueued(content, source, attempt)
344	      && goal !== undefined && goal.id === source.goalId && goal.revision === source.revision
345	      && goal.phase === 'active' && goal.activation === 'armed'
346	      && source.round === goal.roundsStarted + 1
347	    }
348	
349	    ctx.on('agent/pre-step', async ({ agent, messages, signal }, next): Promise<PreStepDecision> => {
350	      const submitted = messages.find((message): message is UserMessage & { source: GoalMessageSource } =>
351	        isGoalRoundSource(message.source))
352	      if (submitted === undefined) return next()
353	      const { content, source } = submitted
354	      const state = stateFor(agent)
355	      let valid = false
356	      try {
357	        valid = validReservation(state, content, source)
358	      } catch (error: unknown) {
359	        ctx.logger.warn(`goal-round-driver: pre-step check failed for agent "${agent.id}": ${renderThrown(error)}`)
360	        disarm(state)
361	      }
362	      if (!valid) {
363	        const attempt = state.attempt
364	        if (attempt !== undefined && sameRound(source, attempt)) {
365	          attempt.stale = true
366	          state.attempt = undefined
367	        }
368	        restoreOtherClaimed(agent, messages, submitted.id)
369	        requestDrive(state)
370	        return { kind: 'reject' }
371	      }
372	      let decision: PreStepDecision
373	      try {
374	        decision = await next()
375	      } catch (error: unknown) {
376	        if (signal.aborted) throw error
377	        // A throwing downstream hook drops the whole step proposal. Clear the
378	        // reservation before the balanced no-step turn returns to idle so the
379	        // next drive pass can reschedule the round.
380	        state.attempt = undefined
381	        requestDrive(state)
382	        throw error
383	      }
384	      if (signal.aborted) {
385	        if (decision.kind === 'enter') restoreOtherClaimed(agent, decision.messages, submitted.id)
386	        return decision
387	      }
388	      if (decision.kind === 'reject') {
389	        state.attempt = undefined
390	        const goal = currentGoal(state)
391	        if (goal !== undefined && goal.id === source.goalId && goal.revision === source.revision
392	          && goal.phase === 'active' && goal.activation === 'armed') {
393	          ctx.goals.block(agent, goalRef(goal), {
394	            code: 'prompt-rejected',
395	            message: 'Goal round was rejected before entering its step.',
396	          })
397	        }
398	        return decision
399	      }
400	      try {
401	        valid = validReservation(state, content, source)
402	      } catch (error: unknown) {
403	        ctx.logger.warn(`goal-round-driver: post-decision check failed for agent "${agent.id}": ${renderThrown(error)}`)
404	        disarm(state)
405	        valid = false
406	      }
407	      if (!valid) {
408	        state.attempt = undefined
409	        restoreOtherClaimed(agent, decision.messages, submitted.id)
410	        requestDrive(state)
411	        return { kind: 'reject' }
412	      }
413	      return decision
414	    })
415	
416	    // Loading a lifecycle driver over existing agents never inherits hidden
417	    // automatic authority from an earlier producer instance.
418	    for (const agent of ctx.agents.list()) {
419	      const state = stateFor(agent)
420	      disarm(state)
421	    }
422	
423	    // Yielded after listener registration, so this close runs first and the
424	    // composite effect removes listeners only after its promise settles.
425	    yield async () => {
426	      const waits: Promise<void>[] = []
427	      for (const state of states.values()) {
428	        state.stopping = true
429	        disarm(state)
430	        const attempt = state.attempt
431	        if (attempt !== undefined) {
432	          attempt.stale = true
433	          /* v8 ignore next -- followup reserves the live agent before publishing a queued attempt */
434	          if (state.agent.status === 'running') {
435	            state.agent.cancel({ kind: 'parent' })
436	            waits.push(state.agent.whenIdle())
437	          }
438	        }
439	        if (state.run !== undefined) waits.push(state.run)
440	      }
441	      await Promise.allSettled(waits)
442	      states.clear()
443	    }
444	  }, 'goal-round-driver lifecycle')
445	}
